Record RootMeta : Type := mkRootMeta {
  rid : RootId;
  stem : string;
  fam : Family;
  invariant_gloss : string;
  tier : Tier;
  phase0_locked : bool;
  split_flag : bool;
  clarity : nat;
  drift : nat;
  provenance : string
}.

Record O8Entry : Type := mkO8Entry {
  o8_root : RootId;
  o8_op : O8;
  o8_status : Status;
  o8_note : string;
  o8_source : string
}.

Record OExtEntry : Type := mkOExtEntry {
  ox_root : RootId;
  ox_op : OExt;
  ox_status : Status;
  ox_note : string;
  ox_source : string
}.

Definition supports (s : Status) : bool :=
  match s with
  | Attested | Admissible | Diachronic => true
  | Blocked | Undecidable => false
  end.

Definition unresolved (s : Status) : bool :=
  match s with
  | Undecidable => true
  | _ => false
  end.

Definition projects_to_o8 (o : OExt) : O8 :=
  match o with
  | TowardX => Toward
  | AwayX => Away
  | ThroughX => Toward
  | IntoX => Toward
  | OutOfX => Away
  | AroundX => Around
  | BesideX => Beside
  | UpwardX => Upward
  | DownwardX => Downward
  | OverX => Upward
  | UnderX => Downward
  | InOnX => Toward
  | BeforeX => Beside
  | AfterX => Beside
  | TogetherX => Together
  | AgainstX => Against
  end.
