Definition cells_for_root (r : RootId) : list O8Entry :=
  filter (fun e => rootId_eqb (o8_root e) r) ledgerO8.

Definition cells_for_root_ext (r : RootId) : list OExtEntry :=
  filter (fun e => rootId_eqb (ox_root e) r) ledgerOExt.

Definition support_count_o8 (r : RootId) : nat :=
  List.length (filter (fun e => supports (o8_status e)) (cells_for_root r)).

Definition unresolved_count_o8 (r : RootId) : nat :=
  List.length (filter (fun e => unresolved (o8_status e)) (cells_for_root r)).

Definition attested_count_o8 (r : RootId) : nat :=
  List.length (filter (fun e =>
    match o8_status e with
    | Attested => true
    | _ => false
    end) (cells_for_root r)).

Definition family_of (r : RootId) : Family := fam (rootMeta r).
Definition tier_of (r : RootId) : Tier := tier (rootMeta r).

Definition roots_with_family (f : Family) : list RootId :=
  filter (fun r => family_eqb (family_of r) f) allRootIds.

Definition roots_with_tier (t : Tier) : list RootId :=
  filter (fun r =>
    match tier_of r, t with
    | tierCore, tierCore => true
    | tierReserve, tierReserve => true
    | tierPressure, tierPressure => true
    | _, _ => false
    end) allRootIds.

Definition eligible_core (r : RootId) : Prop :=
  clarity (rootMeta r) >= 2 /\ drift (rootMeta r) <= 1 /\ support_count_o8 r >= 3.

Definition retier (r : RootId) (t : Tier) (m : RootMeta) : RootMeta :=
  if rootId_eqb r (rid m)
  then mkRootMeta (rid m) (stem m) (fam m) (invariant_gloss m) t
         (phase0_locked m) (split_flag m) (clarity m) (drift m) (provenance m)
  else m.

Definition mark_split (r : RootId) (b : bool) (m : RootMeta) : RootMeta :=
  if rootId_eqb r (rid m)
  then mkRootMeta (rid m) (stem m) (fam m) (invariant_gloss m) (tier m)
         (phase0_locked m) b (clarity m) (drift m) (provenance m)
  else m.

Definition set_o8_status (r : RootId) (o : O8) (s : Status) (e : O8Entry) : O8Entry :=
  if andb (rootId_eqb r (o8_root e)) (o8_eqb o (o8_op e))
  then mkO8Entry (o8_root e) (o8_op e) s (o8_note e) (o8_source e)
  else e.

Definition retier_all (r : RootId) (t : Tier) : list RootMeta :=
  map (retier r t) allRoots.

Definition split_all (r : RootId) (b : bool) : list RootMeta :=
  map (mark_split r b) allRoots.

Definition update_o8_statuses (r : RootId) (o : O8) (s : Status) : list O8Entry :=
  map (set_o8_status r o s) ledgerO8.

